mk(E4,"exploring-our-neighbourhood","landmarks-and-finding-our-way","Landmarks and finding our way","landmark","Rani told her friend to turn at the temple.\n\"A temple is a landmark,\" said her father.",["A landmark is a place that is easy to recognise, like a temple or a big tree.","We use landmarks to give directions.","Directions are left, right, straight, north and south."],["landmark","direction","left"],Q("A landmark is","an easy-to-find place","a toy","a food","We use landmarks for directions.","Left and right are not directions.","landmark"),"Landmarks help us find our way.",["Use landmarks.","Give directions."])
